import express from 'express';

const produk = [
  { id: 1, nama: 'Kopi Susu', harga: 18000 },
  { id: 2, nama: 'Teh Tarik', harga: 12000 },
  { id: 3, nama: 'Es Kopi', harga: 15000 },
];
const app = express();
app.get('/produk', (req, res) => {
  const q = String(req.query.q ?? '').toLowerCase();
  const maks = Number(req.query.maks ?? Infinity);
  res.json(produk.filter((p) => p.nama.toLowerCase().includes(q) && p.harga <= maks).map((p) => p.nama));
});
app.get('/produk/:id', (req, res) => {
  const id = Number(req.params.id);
  if (!Number.isInteger(id)) return res.status(400).json({ error: 'id harus angka' });
  const p = produk.find((x) => x.id === id);
  if (!p) return res.status(404).json({ error: `Produk ${id} tidak ditemukan` });
  res.json(p);
});
const server = app.listen(3000);

const ambil = async (jalur) => {
  const r = await fetch('http://localhost:3000' + jalur);
  console.log(jalur, r.status, await r.json());
};
await ambil('/produk?q=kopi&maks=16000');
await ambil('/produk/2');
await ambil('/produk/9');
await ambil('/produk/abc');
server.close();

