import express from 'express';
const menu = [{ id: 1, nama: 'Kopi Susu' }, { id: 2, nama: 'Teh Tarik' }];
const app = express();
app.get('/menu/:id', (req, res) => {
  const m = menu.find((x) => x.id === Number(req.params.id));
  if (!m) return res.status(404).json({ error: 'Menu tidak ada' });
  res.json(m);
});
const server = app.listen(3000);
for (const id of [2, 9]) {
  const r = await fetch(`http://localhost:3000/menu/${id}`);
  console.log(r.status, await r.json());
}
server.close();

