import express from 'express';
const app = express();
app.get('/kali/:a/:b', (req, res) => {
  const hasil = Number(req.params.a) * Number(req.params.b);
  res.json({ hasil });
});
const server = app.listen(3000);
const d = await (await fetch('http://localhost:3000/kali/6/7')).json();
console.log(d.hasil);
server.close();
